async def act(page):
    # Navigate to the site root where a 'Recent Posts' widget is commonly exposed
    # Use a relative goto as requested.
    await page.goto('/')
    await page.wait_for_load_state('networkidle')

    # 1) Try to find an explicit heading named 'Recent Posts'.
    recent_heading = page.get_by_role("heading", name="Recent Posts")
    if await recent_heading.count() > 0:
        heading = recent_heading.first
    else:
        # 2) Fallbacks: region or complementary landmark named 'Recent Posts'
        recent_region = page.get_by_role("region", name="Recent Posts")
        if await recent_region.count() > 0:
            heading = recent_region.first
        else:
            recent_comp = page.get_by_role("complementary", name="Recent Posts")
            if await recent_comp.count() > 0:
                heading = recent_comp.first
            else:
                # 3) Last-resort: scan all headings and match visible text containing 'Recent Posts'
                headings = page.get_by_role("heading")
                h_count = await headings.count()
                heading = None
                for i in range(h_count):
                    h = headings.nth(i)
                    try:
                        txt = (await h.inner_text()).strip()
                    except Exception:
                        txt = ""
                    if "Recent Posts" in txt:
                        heading = h
                        break

                if heading is None:
                    # 4) Also try scanning complementary / region nodes' visible text for the phrase
                    comps = page.get_by_role("complementary")
                    c_count = await comps.count()
                    for i in range(c_count):
                        c = comps.nth(i)
                        try:
                            txt = (await c.inner_text()).strip()
                        except Exception:
                            txt = ""
                        if "Recent Posts" in txt:
                            heading = c
                            break

                if heading is None:
                    raise Exception("'Recent Posts' heading or region not found on the homepage.")

    # 5) Find a sensible container that contains the heading. Try common container roles.
    container = None
    for role in ("complementary", "region", "navigation", "group", "list", "aside", "section"):
        candidates = page.get_by_role(role).filter(has=heading)
        if await candidates.count() > 0:
            container = candidates.first
            break

    # If no semantic container found, use the heading itself as the container.
    if container is None:
        container = heading

    # 6) Within the container, find link children and click the second one (index 1).
    links = container.get_by_role("link")
    links_count = await links.count()
    if links_count < 2:
        raise Exception("Less than two links were found in the 'Recent Posts' section; cannot click the second-most-recent post.")

    # Click the second-most-recent post link (final action; may navigate away).
    await links.nth(1).click()

